import { IdGenerator } from '../../application/ports/IdGenerator';
import { AddTaskService } from '../../application/task/AddTaskService';
import { AssignTaskService } from '../../application/task/AssignTaskService';
import { CompleteTaskService } from '../../application/task/CompleteTaskService';
import { ListTasksService } from '../../application/task/ListTasksService';
import { TaskController } from '../http/controllers/TaskController';
import { Repositories } from './createRepositories';

export function createTaskController(repositories: Repositories, ids: IdGenerator): TaskController {
  const { projects, tasks, users } = repositories;
  return new TaskController(
    new AddTaskService(projects, tasks, ids),
    new ListTasksService(projects, tasks),
    new AssignTaskService(tasks, users),
    new CompleteTaskService(tasks),
  );
}

